/**
 * Pins the Services panel's markup, whole, as the public dock renders it.
 *
 * Written on the phase base (ARCH-102), before each port card's join of report,
 * activity and calls moved into the model, and needed because the panel and the
 * dock's React files sit outside the devtools mutation glob, so no mutant catches
 * a changed word, test id, attribute or order there. Every cell is compared whole
 * (`outerHTML` of the panel root), never by substring, and the file reaches the
 * panel only through the dock's public props (`reading`, `diagnostics`) and its
 * Services tab. It names nothing the base lacks, so after the move every cell
 * equals its base literal and this file is never edited.
 */
import { assert, describe, it } from "@effect/vitest";
import { act, fireEvent, render, screen } from "@testing-library/react";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Schedule from "effect/Schedule";
import { AttributeResolverNone, attributeResolverRetrying } from "@qadi/core";
import { WiringRead } from "../../src/index.ts";
import { wiringReport } from "../../src/index.ts";
import type { PortActivity, PortCall, PortCallLog, WiringReport } from "../../src/index.ts";
import { DevtoolsDock } from "../../src/react/index.ts";
import type { DevtoolsDockProps } from "../../src/react/index.ts";

/** A diagnostics layer that never builds, so the feed stays `Starting`: unsampled. */
const neverBuilt = { layer: Layer.effectDiscard(Effect.never) };

/** The dock, on its Services tab, and the panel root's markup. */
const servicesMarkup = (props: DevtoolsDockProps): string => {
  render(<DevtoolsDock {...props} />);
  act(() => {
    fireEvent.click(screen.getByRole("button", { name: "Services" }));
  });
  return screen.getByTestId("qadi-services").outerHTML;
};

